      if(D('issue')&&D('expiry')&&D('expiry')<=D('issue'))add('expiry','تاريخ الانتهاء لازم يكون بعد تاريخ الإصدار');
      if(vNum(v.available)&&vNum(v.limit)&&n(v.available)>n(v.limit))add('available','المتاح ما ينفعش يكون أكبر من الحد الائتماني ('+fmt(v.limit)+')');
      if(vNum(v.min)&&vNum(v.statement)&&n(v.statement)>0&&n(v.min)>n(v.statement))add('min','الحد الأدنى ما ينفعش يكون أكبر من المطلوب للسداد');
      if(n(v.statement)>0&&!D('due'))add('due','اكتب آخر ميعاد للسداد بتاع الكشف');
      if(vNum(v.minFixed)&&vNum(v.limit)&&n(v.limit)>0&&n(v.minFixed)>n(v.limit))add('minFixed','الحد الأدنى الثابت أكبر من حد الكارت');
