      if(vNum(v.installment)&&vNum(v.amount)&&n(v.amount)>0&&n(v.installment)>n(v.amount))add('installment','القسط ما ينفعش يكون أكبر من قيمة القرض');
      if(D('nextDue')&&D('maturity')&&D('maturity')<D('nextDue'))add('maturity','تاريخ آخر قسط لازم يكون بعد ميعاد القسط الجاي');
      if(D('start')&&D('maturity')&&D('maturity')<=D('start'))add('maturity','تاريخ الانتهاء لازم يكون بعد تاريخ البداية');
