    if(amt>0){var rw=raw.trim();return aiSay('الـ <b>'+mny(amt)+'</b> دول حصل فيهم إيه؟ اختار وأنا أكمّل معاك خطوة خطوة:<div class="actions">'+[['صرفتهم','صرفت '],['دخلولي','جالي '],['حولتهم','حولت '],['سددت بيهم كارت أو قسط','سددت '],['سلفتهم لحد','سلفت '],['استلفتهم من حد','استلفت ']].map(function(o){return aiAct(o[0],function(){aiAsk(o[1]+rw)})}).join('')+'</div>')}
    var tX=t.replace(/(بنك|مصرف|حساب|كارت|bank|banque|card|بسالك|بسأل|اسال|سؤال|علي|على|عن|ايه|اي|كام|فيه|في)/g,' ').trim(),hX=tX.length>1?hMatch(tX):null;
