    var cg=catGuess(t);if(cg&&cg!=='أخرى'&&t.split(' ').length<=3){var Mc=monthSpend(cg);return aiSay('صرفت على <b>'+esc(cg)+'</b> الشهر ده: <b>'+mny(Mc.tot)+'</b> ('+Mc.n+' عملية).<br>عايز تسجّل صرف جديد عليه؟ اكتب المبلغ، مثلًا "صرفت 150 على '+esc(raw.trim())+' من الكاش".')}
