    S.cards.forEach(function(c){SG.push('كارت '+c.name+' عليه كام؟')});(S.accounts||[]).concat(S.wallets||[]).slice(0,8).forEach(function(o){SG.push('رصيد '+(o.name||o.bank))});S.loans.forEach(function(l){SG.push('قرض '+l.name)});
    var tk=t.split(/[^a-z0-9\u0600-\u06FF]+/).filter(function(w){return w.length>=2&&!/^(في|من|على|علي|عن|ال|انا|انت|ده|دي|اللي|يا|و|او|ولا|هو|هي|ايه|كام)$/.test(w)}).map(function(w){return w.replace(/^(ال|وال|بال|لل)/,'')});
    var sc=SG.map(function(q){var qt=nz(q).split(/[^a-z0-9\u0600-\u06FF]+/).filter(function(w){return w.length>=2}).map(function(w){return w.replace(/^(ال|وال|بال|لل)/,'')}),m=0;
      tk.forEach(function(a){if(qt.some(function(b){var k=Math.min(3,a.length,b.length);return a===b||(k>=3&&(a.indexOf(b.slice(0,k))===0||b.indexOf(a.slice(0,k))===0))}))m++});return [q,m?m/Math.max(qt.length,1)+m:0]}).filter(function(x){return x[1]>0}).sort(function(a,b){return b[1]-a[1]}).slice(0,5);
