  function bankAmbig(t){t=bankNorm(t);if(/(ابوظبي|abudhabi)/.test(t)&&!/(الاول|اول|first|fab|الاسلامي|اسلامي|islamic|adib|التجاري|تجاري|commercial|adcb)/.test(t))return ['fab','adcb','adib'];return null}
