    L.push('غرامة التأخير لو ما دفعتش الحد الأدنى: <b>'+(n(c.lf)?fmt(c.lf)+' ج':'')+(n(c.lp)?(n(c.lf)?' + ':'')+fmt(c.lp)+'% من الحد الأدنى':'')+(!n(c.lf)&&!n(c.lp)?'مش معلنة':'')+'</b>');
    L.push('الحد الأدنى للسداد: '+fmt(c.minP)+'% من الكشف'+(n(c.minF)?' ومش أقل من '+fmt(c.minF)+' ج':''));
