  /* ---- files sent to 3bhady: card / receipt pictures, PDF statements, text/CSV ---- */
  function aiBusy(t){aiKeep();AI.busy=t;aiLog()}
  /* ---- reading Office files on the phone: .xlsx (Excel) and .docx (Word) are zip files of XML ---- */
  function unzipEntries(buf){var u=new Uint8Array(buf),dv=new DataView(buf),e=-1;for(var i=u.length-22;i>=Math.max(0,u.length-70000);i--){if(dv.getUint32(i,true)===0x06054b50){e=i;break}}
    if(e<0)return Promise.reject(new Error('zip'));var n=dv.getUint16(e+10,true),p=dv.getUint32(e+16,true),out={},jobs=[];
    for(var k=0;k<n&&p+46<=u.length;k++){if(dv.getUint32(p,true)!==0x02014b50)break;var meth=dv.getUint16(p+10,true),cs=dv.getUint32(p+20,true),nl=dv.getUint16(p+28,true),xl=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),lo=dv.getUint32(p+42,true);
      var name=new TextDecoder().decode(u.subarray(p+46,p+46+nl));p+=46+nl+xl+cl;
      if(!/^(word\/document\.xml|xl\/sharedStrings\.xml|xl\/worksheets\/sheet\d+\.xml)$/.test(name))continue;
      var ds=lo+30+dv.getUint16(lo+26,true)+dv.getUint16(lo+28,true),data=u.subarray(ds,ds+cs);
      (function(name,meth,data){jobs.push((meth===0?Promise.resolve(data):new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer().then(function(b){return new Uint8Array(b)})).then(function(b){out[name]=new TextDecoder().decode(b)}))})(name,meth,data)}
    return Promise.all(jobs).then(function(){return out})}
  function xmlText(s){return String(s||'').replace(/&#x([0-9a-f]+);/gi,function(_,h){return String.fromCodePoint(parseInt(h,16))}).replace(/&#(\d+);/g,function(_,d){return String.fromCodePoint(+d)}).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&')}
  function officeText(file){if(!window.DecompressionStream)return Promise.reject(new Error('old'));return file.arrayBuffer().then(unzipEntries).then(function(E){
      if(E['word/document.xml'])return xmlText(E['word/document.xml'].replace(/<\/w:p>/g,'\n').replace(/<w:tab\/>/g,' ').replace(/<[^>]+>/g,''));
      var ss=[];String(E['xl/sharedStrings.xml']||'').replace(/<si>([\s\S]*?)<\/si>/g,function(_,x){ss.push(xmlText(x.replace(/<[^>]+>/g,'')));return ''});
      var rows=[];Object.keys(E).filter(function(k){return /worksheets/.test(k)}).sort().forEach(function(k){E[k].replace(/<row[^>]*>([\s\S]*?)<\/row>/g,function(_,r){var cells=[];
        r.replace(/<c([^>]*)>([\s\S]*?)<\/c>/g,function(_,a,c){var v=(c.match(/<v>([\s\S]*?)<\/v>/)||[])[1],t=(a.match(/t="(\w+)"/)||[])[1];if(t==='s'&&v!=null)v=ss[+v];else if(t==='inlineStr')v=xmlText(c.replace(/<[^>]+>/g,''));
          if(v!=null&&v!==''){var num=+v;if(t!=='s'&&t!=='inlineStr'&&t!=='str'&&isFinite(num)&&num>20000&&num<80000&&/s="\d+"/.test(a)&&Math.round(num)===num){var d=new Date(Date.UTC(1899,11,30)+num*864e5);v=('0'+d.getUTCDate()).slice(-2)+'/'+('0'+(d.getUTCMonth()+1)).slice(-2)+'/'+d.getUTCFullYear()}cells.push(xmlText(String(v)))}return ''});
        if(cells.length)rows.push(cells.join('  '));return ''})});
      if(!rows.length)throw new Error('empty');return rows.join('\n')})}
