        if(sk>=2){var prev=AI.stImg;AI.stImg=(prev&&Date.now()-prev.at<180000?prev.t+'\n':'')+t;AI.stImg={t:AI.stImg,at:Date.now()};return aiStmt(AI.stImg.t,file.name)}
        var cd=parseCard(t);
