        var total=null,L=t.split(/\n+/);L.forEach(function(l){if(total==null&&/(total|الاجمالي|الإجمالي|المجموع|المطلوب|amount|net)/i.test(l)){var ns=numIn(l).filter(function(x){return x>0});if(ns.length)total=ns[ns.length-1]}});
        if(total==null){var all=numIn(t).filter(function(x){return x>0&&x<1e6&&String(x).indexOf('.')>0});if(all.length)total=Math.max.apply(null,all)}
        if(total){var c=catGuess(t);return aiSay('ده شكله إيصال 🧾 والإجمالي <b>'+mny(total)+'</b>. أسجّله صرف؟'+'<div class="actions">'+aiAct('سجّل صرف '+fmt(total),function(){openMove('spend',{amt:String(total),kind:c});sheet.auto='receipt';sheet.back={mode:'ai'};renderSheet()},1)+'</div><p class="fine">لو المبلغ غلط عدّله في الشاشة.</p>')}
        aiSay('ما قدرتش أطلّع بيانات واضحة من الصورة. لو كارت: صوّر الوش اللي عليه الرقم في نور كويس. لو إيصال: خلّي الإجمالي واضح. لو كشف حساب: ابعت سكرين واضح للجزء اللي فيه المطلوب والحد الأدنى وآخر ميعاد، أو ابعت الكشف PDF وأنا أقراه كله.')
