  function aiStmt(text,fname){
    var r=stmtParse(text), cards=S.cards, c=r.last4?cards.filter(function(x){return digits(x.number).slice(-4)===r.last4})[0]:null;
    if(!c){var bid=findBank(text);if(bid){var cs=cards.filter(function(x){return x.bankId===bid||nz(x.bank)===nz(bankById(bid).s)});if(cs.length===1)c=cs[0]}}
    var got=r.total!=null||r.min!=null||r.due;
    var H=got?'📄 ده كشف حساب'+(c?' لـ <b>'+esc(c.name)+'</b>':'')+':<br>'+(r.total!=null?'المطلوب: <b>'+mny(r.total)+'</b><br>':'')+(r.min!=null?'الحد الأدنى: <b>'+mny(r.min)+'</b><br>':'')+(r.due?'آخر ميعاد: <b>'+dShort(r.due)+'</b><br>':'')+(r.last4?'الكارت: •••• '+esc(r.last4)+'<br>':''):'📄 قريت الملف.'+(r.tx.length?'':' ما لقيتش فيه المطلوب أو الحد الأدنى أو عمليات أقدر أقراها.');
    function fill(cc){openStmtForm(cc);if(r.total!=null)sheet.v.statement=r.total;if(r.min!=null)sheet.v.min=r.min;if(r.due)sheet.v.due=r.due;sheet.auto='stmt';sheet.back={mode:'ai'};renderSheet();toast('اتملى من الكشف، راجعه واحفظ')}
    if(got){H+='<div class="actions">'+(c?aiAct('سجّل الكشف لـ '+esc(c.name),function(){fill(c)},1):cards.map(function(cc){return aiAct('لـ '+esc(cc.name),function(){fill(cc)})}).join(''))+'</div>';
      if(!c&&!cards.length)H+='<p class="fine">ضيف الكارت الأول، وبعدين ابعت الكشف تاني.</p>'}
    var tx=r.tx.filter(function(x){return !x.credit});
    if(tx.length){var id='st'+Date.now();AI.files[id]=tx;
      H+='<div class="ai-tx"><b>لقيت '+tx.length+' عملية في الكشف</b><p class="fine">علّم اللي عايز تسجّله، وهفتحلك صفحة تراجع فيها كل عملية وتعدّلها قبل ما تتسجل.</p>'+
        tx.slice(0,40).map(function(x,i){return '<label class="ai-row"><input type="checkbox" data-st="'+id+'" data-i="'+i+'"><span>'+dShort(x.date)+' · '+esc(x.desc)+'</span><b>'+fmt(x.amount)+'</b></label>'}).join('')+
        '<div class="actions">'+aiAct('راجع وسجّل المختار',function(){stmtRev(id,c,false)},1)+'</div></div>'}
    aiSay(H);
  }

