    if((!s||!s.has)&&/(مرتب|راتب|salary|salaire)/i.test(String(rec.name||''))&&n(rec.amount)>0){var nw={has:true,name:String(rec.name),amt:n(rec.amount),payDay:+rec.day||1,close:31,to:'',inc:rec.id};nw.payRel=nw.payDay<=15?'next':'same';nw.id='j'+uid().slice(-6);nw.since=salSinceFor(nw);rec.sal=1;S.salary=nw;return true}
