    var ah=acctGate(g,h);if(ah!=null){el.innerHTML=ah+'</div>';try{gMount()}catch(e){}var fe=el.querySelector('#ga-em');if(fe&&!fe.value)setTimeout(function(){try{fe.focus()}catch(e){}},60);return}
