  document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-eye]');if(!b)return;e.preventDefault();e.stopPropagation();var i=document.getElementById(b.getAttribute('data-eye'));if(!i)return;
    var show=i.type==='password';i.type=show?'text':'password';b.innerHTML=show?EYE_OFF:EYE;b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',show?'إخفاء الباسورد':'إظهار الباسورد');try{i.focus()}catch(x){}},true);
